namespace PoloOS.Diagnostics.Core;
public sealed class Kw1281EngineLiveReader:IDisposable
{
    private static readonly byte[] CandidateGroups=[1,6,7,10,11,12]; private static readonly byte[] PollPlan=[6,10,1,6,10,11,6,10,1,7,6,10,12]; private readonly Kw1281ReadOnlySession _session; private readonly DiagLog _log; private readonly List<byte> _available=new(); private int _pollIndex; private double? _rpm,_speed,_pedal,_coolant,_voltage,_fuelTemp,_intakeTemp,_boostAbs,_ambientMbar; private bool? _brakePressed,_clutchPressed; private byte? _pedalSwitchMask;
    public IReadOnlyList<byte> AvailableGroups=>_available; public string Identification=>_session.Identification;
    public Kw1281EngineLiveReader(int deviceIndex,DiagLog log){_log=log;_session=new Kw1281ReadOnlySession(deviceIndex,new ModuleSpec(0x01,"Motor",9600),log);}
    public void Open(){_session.Open();_available.Clear();_pollIndex=0;foreach(var group in CandidateGroups){try{var sample=_session.ReadGroup(group);if(sample is null){_log.Write($"LIVE_GROUP_NAK group={group:D3}");continue;}_available.Add(group);UpdateCache(sample);_log.Write($"LIVE_GROUP_AVAILABLE {sample}");}catch(Exception ex){_log.Write($"LIVE_GROUP_PROBE_FAIL group={group:D3} reason={ex.Message}");}}if(_available.Count==0)throw new InvalidOperationException("No supported KW1281 engine measuring group found.");_log.Write($"LIVE_OPEN ident={Identification} groups="+string.Join(",",_available.Select(x=>x.ToString("D3"))));}
    public EngineLiveFrame ReadFrame(){var group=NextAvailablePollGroup();var sample=_session.ReadGroup(group);if(sample is not null)UpdateCache(sample);return BuildFrame(sample is null?Array.Empty<Kw1281GroupSample>():new[]{sample});}
    private byte NextAvailablePollGroup(){for(var i=0;i<PollPlan.Length;i++){var group=PollPlan[_pollIndex%PollPlan.Length];_pollIndex++;if(_available.Contains(group))return group;}return _available[0];}
    private void UpdateCache(Kw1281GroupSample g){if(g.Group==1){_rpm=ValidOrKeep(SlotValue(g,0),_rpm,0,7000);_coolant=ValidOrKeep(SlotValue(g,3),_coolant,-40,140);}else if(g.Group==6){_speed=ValidOrKeep(SlotValue(g,0),_speed,0,260);if(g.RawBody.Count>5){var mask=g.RawBody[5];_pedalSwitchMask=mask;_brakePressed=(mask&0x09)!=0;_clutchPressed=(mask&0x40)!=0;}}else if(g.Group==7){_fuelTemp=ValidOrKeep(SlotValue(g,0),_fuelTemp,-40,140);_intakeTemp=ValidOrKeep(SlotValue(g,2),_intakeTemp,-40,140);_coolant=ValidOrKeep(SlotValue(g,3),_coolant,-40,140);}else if(g.Group==10){_pedal=ValidOrKeep(SlotValue(g,3),_pedal,0,100);_ambientMbar=ValidOrKeep(SlotValue(g,1),_ambientMbar,500,1300);_boostAbs=ValidOrKeep(SlotValue(g,2),_boostAbs,500,3500);}else if(g.Group==11){_rpm=ValidOrKeep(SlotValue(g,0),_rpm,0,7000);_boostAbs=ValidOrKeep(SlotValue(g,2),_boostAbs,500,3500);}else if(g.Group==12){_voltage=ValidOrKeep(SlotValue(g,2),_voltage,6,18);}}
    private EngineLiveFrame BuildFrame(IReadOnlyList<Kw1281GroupSample> freshGroups){double? boostGauge=null;if(_boostAbs is double abs){var basePressure=_ambientMbar is double amb&&amb>=700&&amb<=1200?amb:1000.0;var gauge=(abs-basePressure)/1000.0;if(double.IsFinite(gauge)&&gauge>=-0.3&&gauge<=3.0)boostGauge=gauge;}return new EngineLiveFrame(DateTime.Now,_rpm,_speed,boostGauge,_pedal,_coolant,_voltage,null,_fuelTemp,_intakeTemp,null,_boostAbs,_ambientMbar,_brakePressed,_clutchPressed,_pedalSwitchMask,freshGroups);}
    private static double? SlotValue(Kw1281GroupSample group,int index)=>index<0||index>=group.Values.Count?null:group.Values[index].NumericValue; private static double? ValidOrKeep(double? candidate,double? oldValue,double min,double max)=>!candidate.HasValue||!double.IsFinite(candidate.Value)||candidate.Value<min||candidate.Value>max?oldValue:candidate.Value; public void Dispose()=>_session.Dispose();
}
